import React, { useState, useEffect } from 'react';
import { usePaymentTerminal } from '../../hooks/usePaymentTerminal';

const PaymentModal = ({ show, cartTotal, onConfirm, onCancel, showToast, paymentMethod }) => {
  // Estados originales para efectivo
  const [cashReceived, setCashReceived] = useState('');
  const [changeDue, setChangeDue] = useState(0);
  
  // Estados para el nuevo sistema de terminales
  const [selectedPaymentMethod, setSelectedPaymentMethod] = useState('efectivo');
  const [selectedTerminal, setSelectedTerminal] = useState('simulator');
  
  // Hook del sistema de pagos
  const {
    connectionStatus,
    isProcessing,
    paymentStatus,
    currentTransaction,
    availableTerminals,
    connectTerminal,
    processPayment,
    cancelPayment,
    disconnect,
    isConnected,
    terminalType
  } = usePaymentTerminal();

  const formatPrice = (price) =>
    new Intl.NumberFormat('es-CL', {
      style: 'currency',
      currency: 'CLP',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(price);

  // Reset estados cuando se abre/cierra el modal
  useEffect(() => {
    if (show) {
      setCashReceived('');
      setChangeDue(0);
      setSelectedPaymentMethod('efectivo');
      // No desconectar terminal automáticamente para mantener conexión
    }
  }, [show]);

  // Calcular cambio para efectivo
  useEffect(() => {
    const received = parseInt(cashReceived, 10) || 0;
    setChangeDue(received >= cartTotal ? received - cartTotal : 0);
  }, [cashReceived, cartTotal]);

  const handleInput = (e) => {
    const value = e.target.value.replace(/[^0-9]/g, '');
    setCashReceived(value);
  };

  const handleAutoComplete = () => {
    setCashReceived(cartTotal.toString());
  };

  // Conectar terminal seleccionado
  const handleConnectTerminal = async () => {
    if (!selectedTerminal) {
      if (showToast) showToast('Error', 'Selecciona un terminal', 'error');
      return;
    }

    try {
      const connected = await connectTerminal(selectedTerminal, {
        timeout: 10000,
        successRate: 0.95 // Para simulador
      });
      
      if (connected) {
        if (showToast) showToast('Éxito', `Terminal ${selectedTerminal} conectado`, 'success');
      } else {
        if (showToast) showToast('Error', 'No se pudo conectar al terminal', 'error');
      }
    } catch (error) {
      if (showToast) showToast('Error', `Error de conexión: ${error.message}`, 'error');
    }
  };

  // Procesar pago según método seleccionado
  const handleConfirm = async () => {
    if (selectedPaymentMethod === 'efectivo') {
      // Lógica original para efectivo
      const received = parseInt(cashReceived, 10) || 0;
      if (received < cartTotal) {
        if (showToast) showToast('Monto Insuficiente', 'El monto recibido es menor que el total de la venta.', 'error');
        return;
      }
      onConfirm(received, changeDue, 'efectivo');
    } 
    else if (selectedPaymentMethod === 'terminal') {
      // Nueva lógica para terminal
      if (!isConnected) {
        if (showToast) showToast('Error', 'Debe conectar el terminal primero', 'error');
        return;
      }

      try {
        const result = await processPayment(cartTotal, {
          description: `Venta POS - ${new Date().toISOString().split('T')[0]}`,
          currency: 'CLP'
        });

        if (result.success) {
          // Pago exitoso - pasar resultado al parent
          onConfirm(cartTotal, 0, 'tarjeta', result);
          if (showToast) showToast('Éxito', '¡Pago procesado exitosamente!', 'success');
        } else {
          // Pago falló
          if (showToast) showToast('Error', result.error || 'Error en el pago', 'error');
        }
      } catch (error) {
        if (showToast) showToast('Error', `Error al procesar pago: ${error.message}`, 'error');
      }
    }
  };

  // Cancelar pago en progreso
  const handleCancelPayment = async () => {
    try {
      await cancelPayment();
      if (showToast) showToast('Cancelado', 'Pago cancelado', 'info');
    } catch (error) {
      if (showToast) showToast('Error', `Error al cancelar: ${error.message}`, 'error');
    }
  };

  if (!show) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-lg p-6 max-w-sm w-full">
        <h5 className="font-bold mb-2">Confirmar Venta</h5>
        <p className="mb-4">Total a pagar: <strong>{formatPrice(cartTotal)}</strong></p>
        {paymentMethod === 'Efectivo' ? (
          <>
            <div className="mb-3">
              <label htmlFor="cashReceivedInput" className="block font-medium mb-1">Monto recibido:</label>
              <div className="flex gap-2">
                <input
                  id="cashReceivedInput"
                  type="number"
                  className="border rounded px-3 py-2 flex-1"
                  value={cashReceived}
                  onChange={handleInput}
                  placeholder="Ingrese el monto..."
                  min="0"
                  autoFocus
                />
                <button
                  type="button"
                  className="bg-blue-500 hover:bg-blue-600 text-white rounded px-3 py-2 text-sm font-medium"
                  onClick={handleAutoComplete}
                  title="Autocompletar monto exacto"
                >
                  Exacto
                </button>
              </div>
            </div>
            <div className="flex justify-between mb-3 font-bold">
              <span>Vuelto:</span>
              <span>{formatPrice(changeDue)}</span>
            </div>
            <div className="flex justify-end gap-2">
              <button className="bg-gray-300 hover:bg-gray-400 text-gray-800 rounded px-4 py-2" onClick={onCancel}>Cancelar</button>
              <button
                className="bg-green-600 hover:bg-green-700 text-white rounded px-4 py-2"
                onClick={handleConfirm}
                disabled={parseInt(cashReceived, 10) < cartTotal || !cashReceived}
              >
                Pagar
              </button>
            </div>
          </>
        ) : paymentMethod === 'Tarjeta' ? (
          <>
            <div className="mb-6 text-center">
              <span className="block text-lg font-semibold mb-2">Pago con Tarjeta</span>
              <span className="block text-2xl font-bold text-green-700">{formatPrice(cartTotal)}</span>
            </div>
            <div className="flex justify-end gap-2">
              <button className="bg-gray-300 hover:bg-gray-400 text-gray-800 rounded px-4 py-2" onClick={onCancel}>Cancelar</button>
              <button
                className="bg-blue-600 hover:bg-blue-700 text-white rounded px-4 py-2"
                onClick={() => onConfirm(null, null)}
              >
                Completar venta
              </button>
            </div>
          </>
        ) : null}
      </div>
    </div>
  );
};

export default PaymentModal;
